import { jsxs, jsx } from 'react/jsx-runtime';
import { useState, useRef, useCallback, useMemo, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { Overlay } from './Overlay.js';
import { OverlayContext } from './OverlayContext.js';
import { OverlayIdContext } from './OverlayIdContext.js';

const OverlayProvider = ({ children, container, className, closeOnBack = true, closeOnBackdropClick = true, unmountOn = 'exit', }) => {
    const [overlays, setOverlays] = useState([]);
    const countRef = useRef(0);
    const removeOverlay = useCallback((id) => {
        setOverlays((overlays) => overlays.filter((overlay) => overlay.id !== id));
    }, []);
    const close = useCallback((id) => {
        setOverlays((overlays) => overlays.map((overlay) => {
            if (overlay.id === id) {
                if (overlay.onClose) {
                    overlay.onClose();
                }
                return {
                    ...overlay,
                    isActive: false,
                };
            }
            return overlay;
        }));
    }, []);
    const pop = useCallback((isBack = false) => {
        const last = overlays.findLast((overlay) => overlay.isActive && (!isBack || overlay.closeOnBack));
        if (!last) {
            return false;
        }
        close(last.id);
        return true;
    }, [overlays, close]);
    const push = useCallback((children, option) => {
        const id = ++countRef.current;
        setOverlays((overlays) => [
            ...overlays,
            {
                isActive: true,
                id,
                children,
                requestUnmount() {
                    removeOverlay(id);
                },
                ...option,
            },
        ]);
        if (option?.closeOnBack) {
            window.history.pushState({}, '', '');
        }
    }, [removeOverlay]);
    const contextValue = useMemo(() => ({
        className,
        closeOnBack,
        closeOnBackdropClick,
        unmountOn,
        push,
        pop,
        close,
    }), [className, closeOnBack, closeOnBackdropClick, unmountOn, push, pop, close]);
    useEffect(() => {
        const handlePopState = () => {
            pop(true);
        };
        window.addEventListener('popstate', handlePopState);
        return () => {
            window.removeEventListener('popstate', handlePopState);
        };
    }, [pop]);
    return (jsxs(OverlayContext.Provider, { value: contextValue, children: [children, typeof window !== 'undefined' &&
                createPortal(overlays.map((overlay) => (jsx(OverlayIdContext.Provider, { value: overlay.id, children: jsx(Overlay, { ...overlay, children: overlay.children }) }, overlay.id))), container)] }));
};

export { OverlayProvider };
