import { jsx, Fragment } from 'react/jsx-runtime';
import React, { useState, useCallback, useEffect } from 'react';
import './TransitionGroupContext.js';
import { TransitionChild } from './TransitionChild.js';

const filterChildren = (children) => {
    const result = [];
    if (Array.isArray(children)) {
        for (const child of children) {
            if (!React.isValidElement(child)) {
                continue;
            }
            result.push({ children: child, isUnmounted: false, id: 0 });
        }
    }
    else {
        if (React.isValidElement(children)) {
            result.push({ children, isUnmounted: false, id: 0 });
        }
    }
    return result;
};
const TransitionGroup = ({ children }) => {
    const [rendered, setRendered] = useState(() => filterChildren(children));
    const handleRequestUnmount = useCallback((key) => {
        setRendered((rendered) => rendered.filter((child) => child.children.key !== key));
    }, []);
    useEffect(() => {
        setRendered((rendered) => {
            const presentChildren = [...filterChildren(children)];
            const presentKeys = new Set(presentChildren.map((child) => child.children.key));
            for (let i = 0; i < rendered.length; i++) {
                const child = rendered[i];
                if (presentKeys.has(child.children.key)) {
                    // unmount중인 요소와 같은 key를 가진 요소가 또 들어온 경우, requestUnmount를 기다리지 않고 바로 제거한다.
                    if (child.isUnmounted) {
                        const presentChild = presentChildren.find((presentChild) => presentChild.children.key === child.children.key);
                        if (presentChild !== undefined) {
                            /**
                             * 새 요소는 unmount 중인 요소보다 id값을 1 높게 설정해 준다.
                             * - id는 렌더 트리에서 기존 요소를 제거할 때 활용한다.
                             */
                            presentChild.id = child.id + 1;
                        }
                        rendered.splice(i--, 1);
                    }
                    continue;
                }
                child.isUnmounted = true;
                presentChildren.splice(i, 0, child);
            }
            return presentChildren;
        });
    }, [children]);
    return (jsx(Fragment, { children: rendered.map((child) => (jsx(TransitionChild, { elementKey: child.children.key, id: child.id, isUnmounted: child.isUnmounted, onRequestUnmount: handleRequestUnmount, children: child.children }, child.children.key))) }));
};

export { TransitionGroup };
